<?php
require __DIR__.'/../config/conexao.php';require __DIR__.'/../includes/auth.php';exigirPerfil('admin');
$msg='';$erro='';
if(isset($_GET['excluir'])){$pdo->prepare("DELETE FROM aulas WHERE id=?")->execute([(int)$_GET['excluir']]);$msg='Aula excluída.';}
if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=$pdo->prepare("INSERT INTO aulas(professor_id,nome,descricao,dia_semana,horario,duracao_min,vagas) VALUES(?,?,?,?,?,?,?)");$s->execute([(int)$_POST['professor_id'],trim($_POST['nome']),trim($_POST['descricao']),(int)$_POST['dia'],$_POST['horario'],(int)$_POST['duracao'],(int)$_POST['vagas']]);$msg='Aula criada.';}catch(PDOException $e){$erro='Não foi possível criar a aula.';}}
$prof=$pdo->query("SELECT p.id,u.nome FROM professores p JOIN usuarios u ON u.id=p.usuario_id ORDER BY u.nome")->fetchAll();$aulas=$pdo->query("SELECT a.*,u.nome professor FROM aulas a JOIN professores p ON p.id=a.professor_id JOIN usuarios u ON u.id=p.usuario_id ORDER BY a.dia_semana,a.horario")->fetchAll();$dia=[1=>'Segunda',2=>'Terça',3=>'Quarta',4=>'Quinta',5=>'Sexta',6=>'Sábado',7=>'Domingo'];$titulo='Aulas';include __DIR__.'/../includes/header.php';
?>
<div class="mb-4"><h1 class="dashboard-title">Aulas</h1></div><?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif;?><?php if($erro):?><div class="alert alert-danger"><?=$erro?></div><?php endif;?>
<div class="fit-card p-4 mb-4"><h4>Nova aula</h4><form method="post" class="row g-3"><div class="col-md-4"><label class="form-label">Professor</label><select class="form-select" name="professor_id" required><option value="">Selecione</option><?php foreach($prof as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nome'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Nome</label><input class="form-control" name="nome" required></div><div class="col-md-4"><label class="form-label">Dia</label><select class="form-select" name="dia"><?php foreach($dia as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Horário</label><input class="form-control" type="time" name="horario" required></div><div class="col-md-4"><label class="form-label">Duração (min)</label><input class="form-control" type="number" name="duracao" value="60" min="15"></div><div class="col-md-4"><label class="form-label">Vagas</label><input class="form-control" type="number" name="vagas" value="10" min="1"></div><div class="col-12"><label class="form-label">Descrição</label><textarea class="form-control" name="descricao"></textarea></div><div><button class="btn btn-fit">Criar aula</button></div></form></div>
<div class="table-responsive fit-card p-3"><table class="table"><thead><tr><th>Aula</th><th>Professor</th><th>Dia</th><th>Horário</th><th></th></tr></thead><tbody><?php foreach($aulas as $a):?><tr><td><?=htmlspecialchars($a['nome'])?></td><td><?=htmlspecialchars($a['professor'])?></td><td><?=$dia[$a['dia_semana']]?></td><td><?=date('H:i',strtotime($a['horario']))?></td><td><a data-confirm="Excluir esta aula?" class="btn btn-sm btn-outline-danger" href="?excluir=<?=$a['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
